<?php
namespace App\Http\Controllers;
use App\Models\ActivityLog;
use App\Services\Accounting\TradeOpeningBalanceService;
use App\Services\Accounting\JournalPostingService;
use App\Models\Currency;
use App\Models\TradeParty;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class TradePartyController extends Controller {
 private function normalizeMoney($value):mixed {
  if(!is_string($value))return $value;
  $value=strtr($value,['٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9','۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٫'=>'.','٬'=>',','،'=>',']);
  return str_replace(',','',$value);
 }

 public function index(Request $request){abort_unless($request->user()->can('administration.view'),403);$type=$request->validate(['type'=>['nullable',Rule::in(['customer','supplier'])]])['type']??'customer';return view('finance.parties.index',['type'=>$type,'parties'=>TradeParty::with('currencies')->where('type',$type)->latest()->paginate(25)->withQueryString(),'currencies'=>Currency::where('is_active',true)->orderBy('code')->get(),'openingBalances'=>DB::table('trade_opening_balances')->get()->groupBy('trade_party_id')]);}
 public function store(Request $request,TradeOpeningBalanceService $opening,JournalPostingService $posting){abort_unless($request->user()->can('administration.update'),403);if($request->has('opening_balances')){$request->merge(['opening_balances'=>array_map(fn($v)=>$this->normalizeMoney($v),$request->input('opening_balances',[]))]);}$data=$request->validate(['type'=>['required',Rule::in(['customer','supplier'])],'name'=>['required','string','max:180'],'code'=>['nullable','string','max:40',Rule::unique('trade_parties','code')->where('type',$request->input('type'))],'contact_person'=>['nullable','string','max:150'],'phone'=>['nullable','string','max:80'],'email'=>['nullable','email','max:180'],'address'=>['nullable','string','max:2000'],'notes'=>['nullable','string','max:2000'],'currency_ids'=>['sometimes','array','min:1'],'currency_ids.*'=>['required','integer','distinct',Rule::exists('currencies','id')->where('is_active',true)],'opening_date'=>['nullable','required_with:opening_balances','date'],'opening_balances'=>['nullable','array'],'opening_balances.*'=>['nullable','numeric','decimal:0,4','between:0,999999999999.9999'],'opening_directions'=>['nullable','array'],'opening_directions.*'=>['nullable',Rule::in(['they_owe_us','we_owe_them'])]]);DB::transaction(function()use($data,$request,$opening,$posting){$openingAmounts=$data['opening_balances']??[];$openingDirections=$data['opening_directions']??[];$openingDate=$data['opening_date']??now()->toDateString();unset($data['opening_balances'],$data['opening_directions'],$data['opening_date']);$currencyIds=$data['currency_ids']??Currency::where('is_active',true)->pluck('id')->all();unset($data['currency_ids']);if(!$currencyIds)throw ValidationException::withMessages(['name'=>'Configure an active currency before adding a customer or supplier.']);$party=TradeParty::create($data+['is_active'=>true,'created_by'=>$request->user()->id]);$party->currencies()->sync($currencyIds);foreach($currencyIds as $id)$party->provisionLedgerAccountsForCurrency((int)$id);foreach($openingAmounts as $currencyId=>$amount){if($amount===null||$amount==='')continue;if(!in_array((int)$currencyId,array_map('intval',$currencyIds),true))throw ValidationException::withMessages(['opening_balances'=>'Opening balance currency must be selected.']);$direction=$openingDirections[$currencyId]??($party->type==='customer'?'they_owe_us':'we_owe_them');$signed=$direction===($party->type==='customer'?'they_owe_us':'we_owe_them')?(string)$amount:'-'.(string)$amount;$opening->post($party,(int)$currencyId,$signed,$openingDate,$request->user()->id,$posting);}ActivityLog::record('trade_party.created','trade_party',$party->id,ucfirst($party->type).' created: '.$party->name);});return redirect()->route('finance.parties.index',['type'=>$data['type']])->with('status','Trade party and currency-specific ledger accounts created.');}
 public function addCurrency(Request $request,TradeParty $party){abort_unless($request->user()->can('administration.update'),403);$data=$request->validate(['currency_id'=>['required',Rule::exists('currencies','id')->where('is_active',true)]]);DB::transaction(function()use($party,$data){if($party->currencies()->whereKey($data['currency_id'])->exists())throw ValidationException::withMessages(['currency_id'=>'Currency already enabled.']);$party->provisionLedgerAccountsForCurrency((int)$data['currency_id']);$party->currencies()->attach($data['currency_id']);ActivityLog::record('trade_party.currency_added','trade_party',$party->id,'Currency enabled for '.$party->name);});return back()->with('status','Currency and ledger accounts enabled.');}
 public function openingBalance(Request $request,TradeParty $party,TradeOpeningBalanceService $opening,JournalPostingService $posting){abort_unless($request->user()->can('administration.update'),403);$request->merge(['amount'=>$this->normalizeMoney($request->input('amount'))]);$data=$request->validate(['currency_id'=>['required','integer','exists:currencies,id'],'amount'=>['required','numeric','gt:0','decimal:0,4','max:999999999999.9999'],'direction'=>['required',Rule::in(['they_owe_us','we_owe_them'])],'balance_date'=>['required','date']]);DB::transaction(function()use($party,$data,$opening,$posting,$request){$signed=$data['direction']===($party->type==='customer'?'they_owe_us':'we_owe_them')?(string)$data['amount']:'-'.(string)$data['amount'];$opening->post($party,(int)$data['currency_id'],$signed,$data['balance_date'],$request->user()->id,$posting);ActivityLog::record('trade_party.opening_balance','trade_party',$party->id,'Opening balance posted for '.$party->name);});return back()->with('status','Opening balance posted successfully.');}

}
